{"op":"add","path":"/root","value":"page"}
{"op":"add","path":"/elements/page","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"children":["composer","returns"]}}
{"op":"add","path":"/elements/composer","value":{"type":"Composer","props":{"headline":"Turn a rough brief into deck directions","lede":"Describe the deck in a few words and get several visual directions, each a theme with its title slide.","runLabel":"Draft my directions","columns":"2","hint":"Needs a topic to start."},"on":{"press":[{"action":"validateForm"},{"action":"run"}]},"children":["deck-group","look-group"]}}
{"op":"add","path":"/elements/deck-group","value":{"type":"FieldGroup","props":{"title":"The deck"},"children":["topic","goal","audience"]}}
{"op":"add","path":"/elements/topic","value":{"type":"Input","props":{"label":"Topic","name":"topic","placeholder":"e.g. Series A pitch for a solar-storage startup","value":{"$bindState":"/inputs/brief/topic"},"checks":[{"type":"required","message":"Add a topic to draft directions."}]},"children":[]}}
{"op":"add","path":"/elements/goal","value":{"type":"Segmented","props":{"label":"Goal","name":"goal","options":["pitch investors","sell to clients","internal training","keynote"],"value":{"$bindState":"/inputs/brief/goal"}},"children":[]}}
{"op":"add","path":"/elements/audience","value":{"type":"Segmented","props":{"label":"Audience","name":"audience","options":["executives","technical team","general public"],"value":{"$bindState":"/inputs/brief/audience"}},"children":[]}}
{"op":"add","path":"/elements/look-group","value":{"type":"FieldGroup","props":{"title":"The look"},"children":["tone","brand-guidelines","references"]}}
{"op":"add","path":"/elements/tone","value":{"type":"Segmented","props":{"label":"Tone","name":"tone","options":["formal","playful","innovative","trustworthy","artsy"],"value":{"$bindState":"/inputs/brief/tone"}},"children":[]}}
{"op":"add","path":"/elements/brand-guidelines","value":{"type":"Textarea","props":{"label":"Brand guidelines","name":"brand_guidelines","placeholder":"Colours, fonts, logo rules…","rows":3,"value":{"$bindState":"/inputs/brief/brand_guidelines"}},"children":[]}}
{"op":"add","path":"/elements/references","value":{"type":"Textarea","props":{"label":"References","name":"existing_references","placeholder":"Templates or past decks to follow, or to steer clear of.","rows":3,"value":{"$bindState":"/inputs/brief/existing_references"}},"children":[]}}
{"op":"add","path":"/elements/returns","value":{"type":"Stack","props":{"direction":"vertical","gap":"sm","align":"center"},"children":["returns-note"]}}
{"op":"add","path":"/elements/returns-note","value":{"type":"Text","props":{"text":"You'll get several directions, one per theme, each with a title slide drawn in it.","variant":"muted"},"children":[]}}
